import{_ as r,a0 as a,w as p,s as d,ao as s,I as t,x as e,a1 as o,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在基于RedHat与Debian的系统上安装Wine 最新的开发版本 | LCTT x X-CMD","titleTemplate":false,"description":"在基于RedHat与Debian的系统上安装Wine 最新的开发版本 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在基于RedHat与Debian的系统上安装Wine 最新的开发版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在基于RedHat与Debian的系统上安装Wine 最新的开发版本 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/Wine 1.7.29 (Development Version) Released – Install in RedHat and Debian Based Systems","title":"在基于RedHat与Debian的系统上安装Wine 最新的开发版本","tag":"201410","desc":""},"relativePath":"201410/Wine 1.7.29 (Development Version) Released – Install in RedHat and Debian Based Systems.md","filePath":"[post].md"}'),u={name:"201410/Wine 1.7.29 (Development Version) Released – Install in RedHat and Debian Based Systems.md"};function m(g,n,w,b,f,W){const i=a("Link");return p(),d("div",null,[n[19]||(n[19]=s('<h1 id="在基于redhat与debian的系统上安装wine-最新的开发版本" tabindex="-1">在基于RedHat与Debian的系统上安装Wine 最新的开发版本 <a class="header-anchor" href="#在基于redhat与debian的系统上安装wine-最新的开发版本" aria-label="Permalink to “在基于RedHat与Debian的系统上安装Wine 最新的开发版本”">​</a></h1><p><strong>Wine</strong>,一个在Linux平台上非常受欢迎并且强大的开源应用，有了它，我们可以在Linux平台上完美运行Windows应用与游戏。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/05/Install-Wine-Development-Version.png" alt="Install Wine (Development Version) in Linux"></p><p><em>在Linux上安装Wine（开发版本）</em></p><p>WineHQ团队，近期宣布了一个新的开发版本<strong>Wine1.7.29</strong>。这个版本带来了诸多重要的特性，并且修复了<strong>44</strong>个bug。</p><p>Wine团队几乎每周都会发布新的开发版本，并且加入许多新特性以及修复漏洞。每个新版本都会支持新的应用与游戏（Windows），这使得Wine在那些想要在Linux下运行Windows应用的用户群体中很流行并且是不可缺少的。</p><p>根据变更日志，这个版本中添加了以下的关键特性：</p><ul><li>在DirectWrite中加入增强的外形塑造与BiDi（译者：bi-directional language）镜像。</li><li>升级了一些页面错误处理方式。</li><li>增加了更多的C运行时函数。</li><li>修复了大量的bug。</li></ul>',8)),t("p",null,[n[1]||(n[1]=e("在官方的 ",-1)),o(i,{href:"http://www.winehq.org/announce/1.7.29"},{default:l(()=>[...n[0]||(n[0]=[e("变更日志",-1)])]),_:1}),n[2]||(n[2]=e(" 中可以找到关于这个版本更多更深入的细节。",-1))]),n[20]||(n[20]=s(`<p>这篇文章指导你在基于<strong>RedHat</strong>与<strong>Debian</strong>的系统，如CentOS，Fedora，Ubuntu，Linux Mint以及其他的发行版中安装最新的开发版本<strong>Wine 1.7.29</strong>。</p><p>##在Linux中安装 Wine 1.7.29 开发版本##</p><p>遗憾的是，目前还没有官方的Wine仓库可以获取基于<strong>RedHat</strong>系统的版本，只能通过编译源码来安装。如果要这么做的话，我们先要安装一些开发包如gcc，flex，bison，libX11-devel freetype-devel　以及开发工具，等等。这些工具都是编译Wine源码所必须的。我们可以通过<strong>YUM</strong>命令来安装这些包。</p><p>##RedHat，Fedora，CentOS##</p><pre><code># yum -y groupinstall &#39;Development Tools&#39;
# yum -y install flex bison libX11-devel freetype-devel
</code></pre><p>然后，使用如下命令下载Wine最新的开发版本（<strong>1.7.29</strong>）以及解压源码包。</p><pre><code>$ cd /tmp
$ wget http://citylan.dl.sourceforge.net/project/wine/Source/wine-1.7.29.tar.bz2
$ tar -xvf wine-1.7.29.tar.bz2 -C /tmp/
</code></pre><p>接下来，使用下列命令编译及安装Wine。</p><p>注：安装过程大概需要<strong>15-20</strong>分钟，这个时间由你的网络速度以及电脑硬件配置决定，在安装过程中需要<strong>root</strong>密码。</p><p>####32位系统####</p><pre><code>$cd wine-1.7.29/
$./tools/wineinstall
</code></pre><p>####64位系统####</p><pre><code>$ cd wine-1.7.29/
$ ./configure --enable-win64
$ make
# make install
</code></pre><p>###Ubuntu，Debian 与 Linux Mint###</p><p>在<strong>Ubuntu</strong>系统下，你可以使用官方的<strong>PPA</strong>方便的安装最新的Wine开发版本。打开一个终端并使用sudo权限执行下列命令。</p><pre><code>$ sudo add-apt-repository ppa:ubuntu-wine/ppa 
$ sudo apt-get update
$ sudo apt-get install wine 1.7 winetricks
</code></pre><p><strong>注</strong>：在写这篇文章时，只能获取<strong>1.7.26</strong>，在官方的仓库中还没有更新到最新版本，但是当仓库更新到<strong>1.7.29</strong>后，使用上面的指令可以安装最新的版本。（译者：为毛我看了版本号是1.6.2......）</p><p>安装成功后，你可以安装或运行任何windows应用或游戏了，示例如下：</p><pre><code>$ wine notepad
$ wine notepad.exe 
$ wine c:\\\\windows\\\\notepad.exe
</code></pre><p><strong>注</strong>：切记，这是一个开发版本，请勿在生产系统上安装它。建议这个版本仅作测试用。</p><p>如果你需要最新的稳定版本，可以参考下列文章，它介绍了如何安装最新的稳定版本。</p>`,21)),t("ul",null,[t("li",null,[o(i,{href:"http://www.tecmint.com/install-wine-in-rhel-centos-and-fedora/"},{default:l(()=>[...n[3]||(n[3]=[e("Install Wine 1.6.2 (Stable) in RHEL, CentOS and Fedora",-1)])]),_:1})]),t("li",null,[o(i,{href:"http://www.tecmint.com/install-wine-on-ubuntu-and-linux-mint/"},{default:l(()=>[...n[4]||(n[4]=[e("Install Wine 1.6.2 (Stable) in Debian, Ubuntu and Mint",-1)])]),_:1})])]),n[21]||(n[21]=t("p",null,"###参考链接###",-1)),t("ul",null,[t("li",null,[o(i,{href:"http://www.winehq.org/"},{default:l(()=>[...n[5]||(n[5]=[e("WineHQ Homepage",-1)])]),_:1})])]),n[22]||(n[22]=t("hr",null,null,-1)),t("p",null,[n[7]||(n[7]=e("via: ",-1)),o(i,{href:"http://www.tecmint.com/install-wine-in-linux/"},{default:l(()=>[...n[6]||(n[6]=[e("http://www.tecmint.com/install-wine-in-linux/",-1)])]),_:1})]),t("p",null,[n[11]||(n[11]=e("作者：",-1)),o(i,{href:"http://www.tecmint.com/author/admin/"},{default:l(()=>[...n[8]||(n[8]=[e("Ravi Saive",-1)])]),_:1}),n[12]||(n[12]=e(" 译者：",-1)),o(i,{href:"https://github.com/SPccman"},{default:l(()=>[...n[9]||(n[9]=[e("SPccman",-1)])]),_:1}),n[13]||(n[13]=e(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:l(()=>[...n[10]||(n[10]=[e("wxy",-1)])]),_:1})]),t("p",null,[n[16]||(n[16]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...n[14]||(n[14]=[e("LCTT",-1)])]),_:1}),n[17]||(n[17]=e(" 原创翻译，",-1)),o(i,{href:"http://linux.cn/"},{default:l(()=>[...n[15]||(n[15]=[e("Linux中国",-1)])]),_:1}),n[18]||(n[18]=e(" 荣誉推出",-1))])])}const C=r(u,[["render",m]]);export{T as __pageData,C as default};
